cypress_script:
describe('HTTP Status Codes Page', () => {
  it('should navigate to the 200 status code page', () => {
    cy.visit('https://the-internet.herokuapp.com/status_codes');
    cy.get('a').contains('200').click();
    cy.url().should('eq', 'https://the-internet.herokuapp.com/status_codes/200');
  });
  it('should not navigate when clicking on an invalid link', () => {
    cy.visit('https://the-internet.herokuapp.com/status_codes');
    cy.get('a').contains('999').click();
    cy.url().should('eq', 'https://the-internet.herokuapp.com/status_codes');
    cy.get('#flash-messages').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('HTTP Status Codes Page', () => {
  test('should navigate to the 200 status code page', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/status_codes');
    await page.click('text=200');
    expect(page.url()).toBe('https://the-internet.herokuapp.com/status_codes/200');
  });
  test('should not navigate when clicking on an invalid link', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/status_codes');
    await page.click('text=999');
    expect(page.url()).toBe('https://the-internet.herokuapp.com/status_codes');
    const flashMessages = await page.locator('#flash-messages');
    expect(await flashMessages.isVisible()).toBe(true);
  });
});
